import{_ as t,o as s,c as e,ai as n}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"家庭与个人","description":"把 Grok Bot 用在生活里：出行规划、账单整理、学习计划、家庭事务提醒。","frontmatter":{"related":["/templates/personal-life-assistant","/start/five-things-day-one","/basics/safety-approvals"],"title":"家庭与个人","description":"把 Grok Bot 用在生活里：出行规划、账单整理、学习计划、家庭事务提醒。","section":"roles","order":6,"tags":["角色","个人","家庭","生活"],"sources":["https://docs.x.ai/grok-bot/overview","https://docs.x.ai/grok-bot/approvals-security-and-privacy","https://docs.x.ai/grok-bot/mobile"],"wordCount":341,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"家庭与个人 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"把 Grok Bot 用在生活里：出行规划、账单整理、学习计划、家庭事务提醒。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/roles/family-personal"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/roles-family-personal-a4a55bcc84.png"}],["meta",{"property":"og:image:alt","content":"家庭与个人 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"家庭与个人 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"把 Grok Bot 用在生活里：出行规划、账单整理、学习计划、家庭事务提醒。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/roles-family-personal-a4a55bcc84.png"}],["meta",{"name":"twitter:image:alt","content":"家庭与个人 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/roles/family-personal"}]]},"headers":[],"relativePath":"roles/family-personal.md","filePath":"roles/family-personal.md","lastUpdated":1792485206000}'),o={name:"roles/family-personal.md"};function i(l,a,p,r,c,d){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="家庭与个人" tabindex="-1">家庭与个人 <a class="header-anchor" href="#家庭与个人" aria-label="Permalink to &quot;家庭与个人&quot;">​</a></h1><p>Grok Bot 不只是工作工具。生活里那些琐碎但需要花时间查、比、记的事，同样可以交给它，而且手机上随时能发语音交代。</p><h2 id="典型工作" tabindex="-1">典型工作 <a class="header-anchor" href="#典型工作" aria-label="Permalink to &quot;典型工作&quot;">​</a></h2><ul><li>出行规划：行程、交通、住宿比较、打包清单。</li><li>账单和票据：整理电子发票、信用卡账单，按月汇总开支。</li><li>学习计划：为自己或孩子制定学习计划，找学习资源。</li><li>家庭事务提醒：证件到期、保险续费、体检、纪念日。</li><li>采购比较：大件物品的参数和价格对比。</li></ul><h2 id="示例提示词" tabindex="-1">示例提示词 <a class="header-anchor" href="#示例提示词" aria-label="Permalink to &quot;示例提示词&quot;">​</a></h2><p><strong>出行规划</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>国庆后想带家人（两个大人、一个 8 岁孩子）出去玩 4 天，高铁 5 小时以内可达。</span></span>
<span class="line"><span>推荐 3 个目的地，每个写：适合孩子的项目、大致预算区间、交通方式、注意事项。</span></span>
<span class="line"><span>只做比较，不要预订任何东西。</span></span></code></pre></div><p><strong>账单整理</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从我的邮箱里找出 9 月所有电子发票和账单邮件，把金额、商家、类别整理成表，</span></span>
<span class="line"><span>按类别汇总，标出比上个月明显增多的类别。</span></span></code></pre></div><p><strong>学习计划</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想用 3 个月时间系统学习数据分析，每周能投入 5 小时，已经会用 Excel。</span></span>
<span class="line"><span>帮我做一份按周的学习计划，每周写目标、推荐的免费资源（附链接）、一个小练习。</span></span></code></pre></div><p><strong>家庭提醒清单</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我建一份家庭事务清单：护照、驾照到期日，车险和家庭保险续费日，</span></span>
<span class="line"><span>年度体检时间（信息我稍后语音告诉你）。存成文件，并在每项到期前 30 天提醒我。</span></span></code></pre></div><h2 id="推荐例程" tabindex="-1">推荐例程 <a class="header-anchor" href="#推荐例程" aria-label="Permalink to &quot;推荐例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周日晚上 8 点，给我一份下周家庭安排：日历里的家庭活动、即将到期的事项、</span></span>
<span class="line"><span>需要采购的东西（根据我平时提到的清单）。用语音备忘读给我听。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">用手机最方便</p><p>生活类的事随手就想起来，用手机 App 语音输入或语音对话交代最顺手。在 iPhone 上还可以通过系统分享把照片、链接直接发给 Bot。</p></div><div class="warning custom-block"><p class="custom-block-title">常见坑</p><ul><li><strong>让 Bot 自己下单付款</strong>：支付确认一定由你亲自完成，Bot 会把这一步交给你。</li><li><strong>把证件照片长期留在云电脑上</strong>：处理完及时删除。</li><li><strong>把健康、财务建议当专业意见</strong>：Bot 能帮你整理信息和问题清单，结论请咨询专业人士。</li><li><strong>家人的隐私</strong>：涉及他人的信息，只放必要的部分。</li></ul></div>`,17)])])}const m=t(o,[["render",i]]);export{h as __pageData,m as default};
